// we add onSend hook to compute trailer
fastify.addHook('onSend', async function(request, reply, payload) {
  // if no trailers set in reply, we skip it
  if(reply[trailer].length) return payload
  const trailers = Object.create(null)
  // if payload is stream, as we cannot read the stream twice. Pass null to the callback
  const trailerPayload = typeof payload.pipe === 'function' ? null : payload
  const header = []
  for(const { name, compute } of reply[trailer]) {
    trailers[name] = await compute(request, reply, trailerPayload)
